; Polled foreground FM/SSG score and 86 PCM. No IRQ, PIC or PIT ownership.
; All routines use the COM's DS; sound_service preserves every general register.
    db 'ROTO98AUD'
    dw sound_init, sound_service, sound_stop, sound_tick, sound_type, fm_base
    dw music_row, music_score, pcm_table, last_time, time_debt, sound_muted
    dw preview_steps, sound_done, fm_write, probe_opn

sound_init:
    cmp byte ptr [sound_muted], 0
    jne sound_init__clock
    call detect_sound
    cmp byte ptr [sound_type], 0
    je sound_init__clock
    ; Preserve PSG port direction bits (joystick and interrupt straps).
    mov dx, [fm_base]
    mov al, 7
    call fm_read
    and al, 0c0h
    mov [psg_direction], al
    or al, 3fh
    mov ah, al
    mov al, 7
    call fm_write
    mov si, fm_init_table
    mov cx, FM_INIT_PAIRS
sound_init__voice:
    lodsw
    call fm_write
    loop sound_init__voice
    cmp byte ptr [sound_type], 2
    jne sound_init__ssg
    ; OPNA stereo enables for the three compatible FM channels.
    mov ax, 0c0b4h
    call fm_write
    inc al
    call fm_write
    inc al
    call fm_write
    call pcm_init
sound_init__ssg:
    mov dx, [fm_base]
    mov ax, 0508h
    call fm_write
    inc al
    call fm_write
    inc al
    call fm_write
    mov ah, [psg_direction]
    or ah, 38h                   ; tone A/B/C on; noise off
    mov al, 7
    call fm_write
sound_init__clock:
    call sound_time
    mov [last_time], ax
    call sound_tick              ; start first notes at t=0
    ret

detect_sound:
    mov dx, 0a460h
    in al, dx
    and al, 0f0h
    cmp al, 40h
    je detect_sound__id86
    cmp al, 50h
    je detect_sound__id86
detect_sound__compatible:
    mov dx, 0188h
    call probe_opn
    jnc detect_sound__opn
    mov dx, 0288h
    call probe_opn
    jnc detect_sound__opn
    mov dx, 0088h              ; PC-9801-26/K legacy FM base
    call probe_opn
    jc detect_sound__absent
detect_sound__opn:
    mov byte ptr [sound_type], 1
    mov [fm_base], dx
    ret
detect_sound__id86:
    mov dx, 0188h
    cmp al, 50h
    jne detect_sound__check86
    mov dx, 0288h
detect_sound__check86:
    call probe_opn              ; ID alone is not proof that FM is present
    jc detect_sound__compatible
    mov [fm_base], dx
    mov byte ptr [sound_type], 2
detect_sound__absent:
    ret

; Two read/write patterns in an 8-bit PSG tone register, restored even on failure.
; CF=0 iff an OPN-compatible register actually responds at DX.
probe_opn:
    push ax
    push bx
    push cx
    xor al, al
    call fm_read
    jc probe_opn__failure
    mov bl, al
    mov ax, 5500h
    call fm_write
    jc probe_opn__restore_bad
    xor al, al
    call fm_read
    jc probe_opn__restore_bad
    cmp al, 55h
    jne probe_opn__restore_bad
    mov ax, 0aa00h
    call fm_write
    jc probe_opn__restore_bad
    xor al, al
    call fm_read
    jc probe_opn__restore_bad
    cmp al, 0aah
    jne probe_opn__restore_bad
    mov ah, bl
    xor al, al
    call fm_write
    jmp probe_opn__return
probe_opn__restore_bad:
    mov ah, bl
    xor al, al
    call fm_write
probe_opn__failure:
    stc
probe_opn__return:
    pop cx
    pop bx
    pop ax
    ret

; AX = data:register, DX = 188h or 288h. Preserves all registers, returns CF.
fm_write:
    push bx
    push dx
    mov bx, ax
    call fm_ready
    jc fm_write__done
    out dx, al
    call opn_delay
    add dx, 2
    mov al, bh
    out dx, al
    call opn_delay
    mov ax, bx
    clc
fm_write__done:
    pop dx
    pop bx
    ret
fm_read:
    push dx
    call fm_ready
    jc fm_read__done
    out dx, al
    call opn_delay
    add dx, 2
    in al, dx
    clc
fm_read__done:
    pop dx
    ret
fm_ready:
    push ax
    push cx
    mov cx, 2048
fm_ready__busy:
    in al, dx
    test al, 80h
    jz fm_ready__ready
    loop fm_ready__busy
    stc
    jmp fm_ready__done
fm_ready__ready:
    clc
fm_ready__done:
    pop cx
    pop ax
    ret
opn_delay:
    push ax
    push cx
    mov cx, 8
opn_delay__delay:
    in al, 5fh                  ; PC-98 0.6 us I/O wait; >=4.8 us
    loop opn_delay__delay
    pop cx
    pop ax
    ret

; DOS time -> centiseconds within minute (0..5999), including midnight wrap.
sound_time:
    mov ah, 2ch
    int 21h
    mov al, dh
    mov ah, 100
    mul ah
    xor dh, dh
    add ax, dx
    ret
sound_service:
    cmp byte ptr [sound_type], 0
    jne sound_service__active
    cmp word ptr [preview_steps], 0
    je sound_service__return
sound_service__active:
    push ax
    push bx
    push cx
    push dx
    push si
    push di
    push bp
    call sound_time
    mov bx, ax
    sub ax, [last_time]
    jnc sound_service__elapsed
    add ax, 6000
sound_service__elapsed:
    mov [last_time], bx
    ; Cap anomalous pauses; at most four music steps per call.
    cmp ax, 40
    jbe sound_service__accumulate
    mov ax, 40
sound_service__accumulate:
    add [time_debt], ax
    mov bp, 4
sound_service__step:
    cmp word ptr [time_debt], 10     ; 100 ms sixteenth note = 150 BPM
    jb sound_service__done
    sub word ptr [time_debt], 10
    call sound_tick
    dec bp
    jnz sound_service__step
sound_service__done:
    pop bp
    pop di
    pop si
    pop dx
    pop cx
    pop bx
    pop ax
sound_service__return:
    ret

sound_tick:
    cmp byte ptr [sound_done], 0
    je sound_tick__active
    ret
sound_tick__active:
    mov ax, [music_row]
    mov bx, 7
    mul bx
    mov si, music_score
    add si, ax
    cmp byte ptr [sound_type], 0
    je sound_tick__advance
    mov dx, [fm_base]
    xor di, di
sound_tick__fm:
    lodsb
    cmp al, 255                 ; tie bass on alternate sixteenths
    je sound_tick__fm_next
    xor ah, ah
    mov bx, ax
    shl bx, 1
    push bx
    mov ax, di
    mov ah, al
    mov al, 28h
    call fm_write              ; key off
    pop bx
    mov cx, [fm_notes+bx]
    mov ax, di
    add al, 0a4h
    mov ah, ch
    call fm_write              ; FNUM high/block before low
    mov ax, di
    add al, 0a0h
    mov ah, cl
    call fm_write
    mov ax, di
    mov ah, al
    or ah, 0f0h
    mov al, 28h
    call fm_write              ; all four operators key on
sound_tick__fm_next:
    inc di
    cmp di, 3
    jb sound_tick__fm
    xor di, di
sound_tick__psg:
    lodsb
    xor ah, ah
    mov bx, ax
    shl bx, 1
    mov cx, [ssg_notes+bx]
    mov ax, di
    mov ah, cl
    call fm_write
    inc al
    mov ah, ch
    call fm_write
    add di, 2
    cmp di, 6
    jb sound_tick__psg
    cmp byte ptr [sound_type], 2
    jne sound_tick__advance
    lodsb
    call pcm_play
sound_tick__advance:
    inc word ptr [music_row]
    cmp word ptr [music_row], MUSIC_ROWS
    jb sound_tick__preview
    mov word ptr [music_row], 0
sound_tick__preview:
    cmp word ptr [preview_steps], 0
    je sound_tick__return
    dec word ptr [preview_steps]
    jnz sound_tick__return
    mov byte ptr [sound_done], 1
sound_tick__return:
    ret

pcm_init:
    mov dx, 0a66eh
    in al, dx
    mov [pcm_old_mute], al
    and al, 0feh
    out dx, al
    mov dx, 0a468h
    mov al, 04h                ; stopped, 11025 Hz, FIFO IRQ disabled
    out dx, al
    mov dx, 0a46ah
    mov al, 70h                ; signed 8-bit stereo
    out dx, al
    mov dx, 0a466h
    mov al, 0a0h               ; PCM output attenuation = 0
    out dx, al
    ret
pcm_play:
    xor ah, ah
    mov bx, ax
    shl bx, 1
    shl bx, 1
    mov si, [pcm_table+bx]
    mov cx, [pcm_table+bx+2]
    mov dx, 0a468h
    mov al, 0ch                ; stop + reset FIFO, keep rate code 4
    out dx, al
    mov al, 04h
    out dx, al
pcm_play__fill:
    mov dx, 0a466h
    in al, dx
    test al, 80h               ; unexpected full: abandon this hit, never spin
    jnz pcm_play__return
    mov dx, 0a46ch
    lodsb
    out dx, al
    loop pcm_play__fill
    mov dx, 0a468h
    mov al, 84h                ; play, no recording/IRQ
    out dx, al
pcm_play__return:
    ret
sound_stop:
    cmp byte ptr [sound_type], 0
    je sound_stop__return
    mov dx, [fm_base]
    mov ax, 0028h
    call fm_write
    mov ah, 1
    call fm_write
    mov ah, 2
    call fm_write
    mov ax, 0008h
    call fm_write
    inc al
    call fm_write
    inc al
    call fm_write
    mov ah, [psg_direction]
    or ah, 3fh
    mov al, 7
    call fm_write
    mov ax, 3027h
    call fm_write
    cmp byte ptr [sound_type], 2
    jne sound_stop__return
    mov dx, 0a468h
    mov al, 0ch
    out dx, al
    mov al, 04h
    out dx, al
    mov dx, 0a66eh
    mov al, [pcm_old_mute]
    out dx, al
sound_stop__return:
    ret

sound_report:
    mov dx, msg_silent
    cmp byte ptr [sound_type], 0
    je sound_report__print
    mov dx, msg_26
    cmp byte ptr [sound_type], 1
    je sound_report__print
    mov dx, msg_86
sound_report__print:
    mov ah, 09h
    int 21h
    ret

fm_base dw 0188h
sound_type db 0                 ; 0 absent/muted, 1 26K-compatible, 2 verified 86
sound_muted db 0
psg_direction db 0
